85	union GmmaDescriptor
86	{
87	  CUTE_HOST_DEVICE constexpr
88	  GmmaDescriptor() noexcept : desc_(0) {}
89	  CUTE_HOST_DEVICE constexpr
90	  GmmaDescriptor(uint64_t desc) noexcept : desc_(desc) {}
91	  CUTE_HOST_DEVICE constexpr
92	  GmmaDescriptor(GmmaDescriptor const& t) noexcept : desc_(t.desc_) {}
93	  CUTE_HOST_DEVICE constexpr
94	  GmmaDescriptor(GmmaDescriptor && t) noexcept : desc_(t.desc_) {}
95	
96	  CUTE_HOST_DEVICE constexpr
97	  GmmaDescriptor& operator=(GmmaDescriptor const& t) noexcept {
98	    desc_ = t.desc_;
99	    return *this;
100	  }
101	
102	  CUTE_HOST_DEVICE constexpr
103	  GmmaDescriptor& operator=(GmmaDescriptor && t) noexcept {
104	    desc_ = t.desc_;
105	    return *this;
106	  }
107	
108	  uint64_t desc_;
109	  uint32_t reg32_[2];
110	  uint16_t reg16_[4];
111	
112	  // Bitfield implementation avoids the need for shifts in assignment
113	  struct {
114	    // start_address, bit [0,14), 4LSB not included
115	    uint16_t start_address_ : 14, : 2;        // 14 bits [0,14), 2 bits unused
116	    // leading dimension byte offset, bit [16,30), 4LSB not included
117	    // For N: This is the stride from the first col to the second col of the 8x2 brick in INTERLEAVED
118	    //   Unused for all SWIZZLE_* layouts (and assumed to be 1)
119	    // For T: This is the stride from the first 8 rows to the next 8 rows.
120	    uint16_t leading_byte_offset_ : 14, : 2;  // 14 bits [0,14), 2 bits unused
121	    // stride dimension byte offset, bit [32,46), 4LSB not included
122	    // For N: This is the stride from the first 8 rows to the next 8 rows.
123	    // For T: This is the stride fro mthe first 8 cols to the next 8 cols.
124	    uint16_t stride_byte_offset_ : 14, : 2;   // 14 bits [0,14), 2 bits unused
125	    // base_offset, bit [49,52)
126	    // Valid only for SWIZZLE_128B and SWIZZLE_64B
127	    uint8_t : 1, base_offset_ : 3, : 4;       // 1 bit unused, 3 bits [1,4), 4 bits unused
128	    // layout type, bit [62,64)
129	    // SWIZZLE_NONE = 0, SWIZZLE_32B = 3, SWIZZLE_64B = 2, SWIZZLE_128B = 1
130	    uint8_t : 6, layout_type_ : 2;            // 6 bits unused, 2 bits [6,8)
131	  } bitfield;
132	
133	  // Decay to a uint64_t
134	  CUTE_HOST_DEVICE constexpr
135	  operator uint64_t() const noexcept { return desc_; }
136	};
