143	  printf("GmmaDescriptor: 0x%016llx\n",   static_cast<unsigned long long>(t.desc_));
144	  printf("  start_addr :  0x%04x\n",      t.bitfield.start_address_);
145	  printf("  leading_off:  0x%04x (%d)\n", t.bitfield.leading_byte_offset_, t.bitfield.leading_byte_offset_);
146	  printf("  stride_off :  0x%04x (%d)\n", t.bitfield.stride_byte_offset_, t.bitfield.stride_byte_offset_);
147	  printf("  base_offset:  0x%01x\n",      t.bitfield.base_offset_);
148	  printf("  layout_type:  0x%01x (%s)\n", t.bitfield.layout_type_, to_string(static_cast<SM90::GMMA::LayoutType>(t.bitfield.layout_type_)));
149	#endif // !defined(__CUDACC_RTC__)
150	}
