45	// Warpgroup sync primitives
46	
47	CUTE_HOST_DEVICE
48	void
49	warpgroup_arrive()
50	{
51	#if defined(CUTE_ARCH_MMA_SM90A_ENABLED)
52	  cutlass::arch::synclog_emit_warpgroup_arrive(__LINE__);
53	  asm volatile ("wgmma.fence.sync.aligned;\n" ::: "memory");
54	#else
