template <SwizzleMode Swizzle = kSwizzleNone>
__device__ __forceinline__ SmemDesc make_smem_desc(
    const void* smem_base, uint32_t lbo_bytes, uint32_t sbo_bytes,
    uint32_t base_offset = 0u
